"use client";

import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Dialog, DialogOverlay, DialogPortal, DialogTrigger } from "@/components/ui/dialog";

/**
 * Modal — reconciled 1:1 with the KinetixUI design source, node 54857:1322.
 * A structured dialog: header (title + close) · divider · body (description) ·
 * divider · right-aligned footer. `--radius-xl` corner, soft popup shadow.
 *
 * type:
 *   Info          → one primary action ("Got it")
 *   Confirmation  → Cancel + primary ("Confirm")
 *   Warning       → Cancel + primary ("Proceed")
 *   Destructive   → Cancel + destructive ("Delete")
 */
export type ModalType = "Info" | "Confirmation" | "Warning" | "Destructive";

const DEFAULT_ACTION: Record<ModalType, string> = {
  Info: "Got it",
  Confirmation: "Confirm",
  Warning: "Proceed",
  Destructive: "Delete",
};

export interface ModalProps {
  type?: ModalType;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** overrides the type's default action label */
  actionLabel?: string;
  cancelLabel?: string;
  onAction?: () => void;
  onCancel?: () => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: React.ReactNode;
  children?: React.ReactNode;
  className?: string;
}

function Modal({
  type = "Info",
  title,
  description,
  actionLabel,
  cancelLabel = "Cancel",
  onAction,
  onCancel,
  open,
  defaultOpen,
  onOpenChange,
  trigger,
  children,
  className,
}: ModalProps) {
  const showCancel = type !== "Info";

  return (
    <Dialog open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      {trigger && <DialogTrigger asChild>{trigger}</DialogTrigger>}
      <DialogPortal>
        <DialogOverlay />
        <DialogPrimitive.Content
          className={cn(
            // rtl-ok: centering trick, direction-agnostic by construction — same decision as dialog.tsx
            "fixed left-1/2 top-1/2 z-overlay flex w-full max-w-[480px] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-xl bg-background font-sans",
            "shadow-xl",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=open]:duration-fast data-[state=open]:ease-enter data-[state=closed]:duration-instant data-[state=closed]:ease-exit",
            className,
          )}
        >
          <header className="flex items-center justify-between px-6 pb-3 pt-5">
            <DialogPrimitive.Title className="min-w-0 flex-1 text-title-dialog text-foreground">
              {title}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close
              className="rounded-sm opacity-muted outline-none transition-opacity hover:opacity-visible focus-visible:ring-2 focus-visible:ring-ring"
              aria-label="Close"
            >
              <X className="size-5" />
            </DialogPrimitive.Close>
          </header>

          <div className="h-px w-full bg-border" />

          <div className="px-6 py-5">
            {description && (
              <DialogPrimitive.Description className="text-body-md text-muted-foreground">
                {description}
              </DialogPrimitive.Description>
            )}
            {children}
          </div>

          <div className="h-px w-full bg-border" />

          <footer className="flex items-center justify-end gap-3 px-6 py-4">
            {showCancel && (
              <DialogPrimitive.Close asChild>
                <Button variant="Outline" size="lg" onClick={onCancel}>
                  {cancelLabel}
                </Button>
              </DialogPrimitive.Close>
            )}
            <DialogPrimitive.Close asChild>
              <Button
                variant={type === "Destructive" ? "Destructive" : "Primary"}
                size="lg"
                onClick={onAction}
              >
                {actionLabel ?? DEFAULT_ACTION[type]}
              </Button>
            </DialogPrimitive.Close>
          </footer>
        </DialogPrimitive.Content>
      </DialogPortal>
    </Dialog>
  );
}

export { Modal };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened — proven by the trigger having left the document, so a handler
 * that decides not to remove anything leaves focus exactly where the user put it.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
